const json=(body,status=200)=>new Response(JSON.stringify(body),{status,headers:{'content-type':'application/json;charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'}});
const validString=(v,max=180)=>typeof v==='string'&&v.trim().length>0&&v.length<=max;
const testKey=env=>typeof env.SHIPPO_TEST_TOKEN==='string'&&env.SHIPPO_TEST_TOKEN.startsWith('shippo_test_')&&env.SHIPPO_TEST_TOKEN.length>20;
const apiBase='https://api.goshippo.com';
function validateAddress(a){return a&&validString(a.name,120)&&validString(a.street1,180)&&validString(a.city,100)&&validString(a.state,30)&&validString(a.zip,20)&&a.country==='US'&&(!a.phone||validString(a.phone,50))}
function validateParcel(p){return p&&['length','width','height','weight'].every(k=>typeof p[k]==='number'&&Number.isFinite(p[k])&&p[k]>0&&p[k]<2000)&&p.distance_unit==='in'&&p.mass_unit==='kg'}
async function shippo(env,path,body){const response=await fetch(apiBase+path,{method:'POST',headers:{'authorization':'ShippoToken '+env.SHIPPO_TEST_TOKEN,'content-type':'application/json','accept':'application/json'},body:JSON.stringify(body)});const data=await response.json().catch(()=>({message:'Shippo returned unreadable response'}));if(!response.ok)throw Object.assign(new Error(typeof data?.message==='string'?data.message:'Shippo request failed'),{status:response.status});return data}
async function api(request,env,url){if(request.method==='GET'&&url.pathname==='/api/shippo/status')return json({configured:testKey(env),mode:'test',liveDisabled:true});if(request.method!=='POST')return json({error:'Unsupported method'},405);
 if(!testKey(env))return json({error:'Shippo test token is not configured. A shippo_test_ token must be installed as a server secret.'},503);
 let body;try{body=await request.json()}catch{return json({error:'Invalid JSON'},400)}
 try{
  if(url.pathname==='/api/shippo/rates'){if(!validateAddress(body?.from)||!validateAddress(body?.to)||!validateParcel(body?.parcel))return json({error:'Complete the sender, recipient, and positive package measurements. US addresses only.'},422);
    const payload={address_from:body.from,address_to:body.to,parcels:[body.parcel],async:false};
    const result=await shippo(env,'/shipments/',payload);const rates=(result.rates||[]).filter(r=>r&&r.object_id).map(r=>({id:r.object_id,provider:r.provider,service:r.servicelevel?.name||r.servicelevel_name||'',amount:r.amount,currency:r.currency,days:r.estimated_days,object_state:r.object_state,messages:r.messages}));
    return json({mode:'test',shipment_id:result.object_id,rates,shippo_messages:result.messages||[]});
  }
  if(url.pathname==='/api/shippo/test-label'){if(!validString(body?.rate_id,100))return json({error:'Select an existing test rate first'},422);const result=await shippo(env,'/transactions/',{rate:body.rate_id,label_file_type:'PDF_4x6',async:false});if(result.was_test!==true)return json({error:'Shippo did not confirm a test transaction. Label details withheld.'},502);return json({mode:'test',was_test:true,status:result.status,tracking_number:result.tracking_number||null,label_url:result.label_url||null,messages:result.messages||[],transaction_id:result.object_id});}
  return json({error:'Unknown API route'},404);
 }catch(e){return json({error:e.message||'Shippo request failed',upstream_status:e.status||null},e.status>=400&&e.status<=499?422:502)}
}
export function handler(assets){return {async fetch(request,env){const url=new URL(request.url);
 if(url.pathname.startsWith('/api/shippo/')){if(!request.headers.get('oai-authenticated-user-id'))return json({error:'Sign in to the private shipping app first'},401);return api(request,env,url)}
 const path=url.pathname==='/'?'/orders.html':url.pathname;const asset=assets[path];if(!asset)return new Response('Not found',{status:404});return new Response(asset.text,{headers:{'content-type':asset.type,'cache-control':'no-store','x-content-type-options':'nosniff'}});
}}}

export default handler({"/index.html":{"text":"<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta http-equiv=\"refresh\" content=\"0;url=./orders.html\"><title>一一妈咪好物团 · 订单工作台</title></head><body><p><a href=\"./orders.html\">打开订单工作台</a></p></body></html>\n","type":"text/html;charset=utf-8"},"/orders.html":{"text":"<!doctype html>\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>订单工作台 · 一一妈咪好物团</title>\n<style>\n:root{font-family:Inter,\"Segoe UI\",ui-sans-serif,system-ui,sans-serif;color:#18383b;background:#f3f7f6;font-synthesis:none}*{box-sizing:border-box}body{margin:0}header{background:#123b3d;color:#fff;padding:18px max(20px,calc((100vw - 1380px)/2));display:flex;align-items:center;justify-content:space-between;gap:16px}.brand{display:flex;align-items:center;gap:12px}.logo{height:40px;width:40px;border-radius:12px;background:#d8eee7;color:#145d50;display:grid;place-items:center;font-size:22px}.brand h1{font-size:17px;margin:0}.brand p{margin:3px 0 0;font-size:11px;color:#bdd5d2}.topnav{display:flex;gap:8px;align-items:center}.topnav a{color:#d9ebe8;text-decoration:none;padding:9px 12px;border-radius:9px;font-size:13px}.topnav a.active{background:#fff;color:#145d50;font-weight:750}.mode{font-size:11px;background:#daf0e8;color:#17654f;padding:6px 10px;border-radius:20px;font-weight:750}.shell{max-width:1380px;margin:24px auto;padding:0 18px}.heading{display:flex;justify-content:space-between;align-items:end;gap:16px;margin-bottom:18px}.heading h2{font-size:25px;margin:0 0 5px}.muted{color:#687e80;font-size:13px}.controls{display:flex;gap:8px;flex-wrap:wrap}.btn{border:0;border-radius:9px;padding:10px 14px;font:inherit;font-size:13px;font-weight:700;cursor:pointer;background:#176c59;color:#fff}.btn:hover{background:#115744}.btn.secondary{background:#e6efed;color:#315d57}.btn.ghost{background:transparent;color:#176c59;border:1px solid #bdd2cd}.btn:disabled{opacity:.45;cursor:not-allowed}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.stat,.card{background:#fff;border:1px solid #dfe8e6;border-radius:14px;box-shadow:0 3px 14px #173e3b08}.stat{padding:16px}.stat strong{font-size:24px;display:block;color:#153f3d}.stat span{font-size:12px;color:#718584}.layout{display:grid;grid-template-columns:360px 1fr;gap:16px;align-items:start}.card{padding:18px}.card h3{font-size:16px;margin:0 0 13px}.importbox{border:1px dashed #8bb8ad;background:#f4faf8;border-radius:11px;padding:16px;text-align:center}.importbox p{margin:0 0 10px;color:#627b79;font-size:12px}.importbox input{display:none}.field{margin:12px 0}label{display:block;margin-bottom:6px;font-size:12px;font-weight:700;color:#526e6d}input[type=text],select{width:100%;border:1px solid #ceddd9;border-radius:8px;padding:10px 11px;font:inherit;color:#18383b;background:#fff}.searchrow{display:grid;grid-template-columns:1fr 140px;gap:8px;margin:14px 0}.customerlist{max-height:650px;overflow:auto}.customer{padding:11px;border:1px solid #e4ecea;border-radius:10px;margin:7px 0;cursor:pointer;display:flex;justify-content:space-between;gap:10px}.customer:hover,.customer.active{background:#edf7f3;border-color:#76b9a7}.customer b{font-size:13px;display:block}.customer small{font-size:11px;color:#768987;display:block;margin-top:3px}.badge{white-space:nowrap;align-self:center;border-radius:18px;padding:5px 8px;background:#e9efee;color:#617674;font-size:10px;font-weight:750}.badge.ready{background:#d9f1e7;color:#19634d}.badge.warn{background:#fff1d5;color:#805d19}.maincard{min-height:520px}.mainhead{display:flex;justify-content:space-between;align-items:start;gap:12px}.mainhead h3{font-size:19px;margin:0 0 4px}.queuechips{display:flex;gap:7px;flex-wrap:wrap;margin:15px 0}.chip{background:#edf3f2;border-radius:18px;padding:7px 11px;font-size:11px;color:#526b69;cursor:pointer;border:0;font-weight:700}.chip.active{background:#176c59;color:white}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th{text-align:left;padding:10px 8px;color:#748784;border-bottom:1px solid #dfe8e6;font-size:10px;white-space:nowrap}td{padding:11px 8px;border-bottom:1px solid #edf1f0;vertical-align:top}td.product{min-width:250px;max-width:580px;line-height:1.55;white-space:pre-wrap}.money{white-space:nowrap;font-variant-numeric:tabular-nums}.itemstatus{display:flex;align-items:center;gap:8px}.check{height:18px;width:18px;accent-color:#168060;cursor:pointer}.statuslabel{font-size:11px;color:#667d79}.meta{display:flex;gap:10px;flex-wrap:wrap;color:#6d8280;font-size:12px;margin:12px 0 4px}.meta span{background:#f3f7f6;padding:7px 9px;border-radius:8px}.note{padding:11px;border-radius:9px;background:#fff8e8;border:1px solid #f0dfb4;color:#735c22;font-size:12px;line-height:1.5;margin:12px 0}.success{padding:11px;border-radius:9px;background:#eaf6f0;color:#22644d;font-size:12px;margin:12px 0}.empty{padding:42px 18px;text-align:center;color:#849391;background:#f8faf9;border-radius:10px}.foot{color:#8a9997;font-size:11px;padding:14px 2px 35px}.toast{position:fixed;right:22px;bottom:20px;background:#123b3d;color:#fff;padding:12px 16px;border-radius:10px;box-shadow:0 8px 20px #0002;display:none;max-width:360px;font-size:13px}.menu{display:flex;gap:8px}.menu a{color:#fff}.route-label{font-size:11px;color:#5f7774}@media(max-width:920px){.layout{grid-template-columns:1fr}.customerlist{max-height:280px}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:580px){header{padding:14px 12px;align-items:start;flex-direction:column}.topnav{width:100%;overflow:auto}.topnav a{white-space:nowrap}.shell{padding:0 10px;margin:16px auto}.heading{display:block}.controls{margin-top:12px}.stats{gap:8px}.stat{padding:12px}.searchrow{grid-template-columns:1fr}.card{padding:13px}}\n</style></head><body>\n<header><div class=\"brand\"><div class=\"logo\">📦</div><div><h1>一一妈咪好物团 · 订单工作台</h1><p>订单导入 · 到货登记 · 打包发货</p></div></div><nav class=\"topnav\"><a class=\"active\" href=\"./orders.html\">订单与到货</a><a href=\"./shipping.html\">打包与 Shippo</a><span class=\"mode\">私有工作台</span></nav></header>\n<main class=\"shell\"><div class=\"heading\"><div><h2>订单与到货</h2><div class=\"muted\">导入主表，核对异常，并按客户查看全部订单和商品到货进度。</div></div><div class=\"controls\"><button id=\"export\" class=\"btn secondary\">导出当前订单 CSV</button><button id=\"reset\" class=\"btn ghost\">清空本机数据</button></div></div>\n<div class=\"stats\"><div class=\"stat\"><strong id=\"nCustomers\">0</strong><span>客户</span></div><div class=\"stat\"><strong id=\"nOrders\">0</strong><span>订单行</span></div><div class=\"stat\"><strong id=\"nArrived\">0</strong><span>全部到齐客户</span></div><div class=\"stat\"><strong id=\"nReview\">0</strong><span>需要复核</span></div></div>\n<div class=\"layout\"><aside><section class=\"card\"><h3>导入接龙或主表</h3><div class=\"importbox\"><p>支持 .xlsx 或 .csv；商品数据在本机浏览器解析</p><label class=\"btn\" for=\"file\">选择订单文件</label><input id=\"file\" type=\"file\" accept=\".xlsx,.csv\"><div class=\"muted\" id=\"filename\" style=\"margin-top:9px\">尚未导入文件</div></div><div class=\"field\"><label for=\"importMode\">导入方式</label><select id=\"importMode\"><option value=\"append\">追加到当前订单（自动查重并提示疑似重复）</option><option value=\"replace\">用此文件替换本机当前订单</option></select></div><div class=\"note\">首版数据保存在当前浏览器和这台电脑，不会自动同步到其他设备。请定期导出备份；后续阶段会接入持久化数据库。</div><div id=\"importResult\"></div></section><section class=\"card\" style=\"margin-top:14px\"><div class=\"row\"><h3 style=\"margin:0\">客户队列</h3></div><div class=\"searchrow\"><input id=\"search\" type=\"text\" placeholder=\"搜索客户姓名、电话或订单号\"><select id=\"filter\"><option value=\"all\">全部客户</option><option value=\"ready\">全部到齐</option><option value=\"waiting\">待到货 / 部分到货</option><option value=\"review\">需要复核</option><option value=\"pickup\">自提</option><option value=\"mail\">邮寄</option><option value=\"tri\">三谷</option><option value=\"zip95008\">95008 地区</option><option value=\"unassigned\">配送方式待确认</option></select></div><div class=\"customerlist\" id=\"customerList\"><div class=\"empty\">请先导入 Excel 文件</div></div></section></aside>\n<section class=\"card maincard\"><div id=\"detailEmpty\" class=\"empty\">选择左侧客户查看其所有订单和商品。全部到齐的客户会自动进入自提或待打包队列。</div><div id=\"detail\" hidden><div class=\"mainhead\"><div><h3 id=\"customerTitle\"></h3><div id=\"customerSub\" class=\"muted\"></div></div><span class=\"badge\" id=\"customerStatus\"></span></div><div id=\"possibleMatch\"></div><div class=\"meta\" id=\"customerMeta\"></div><div class=\"queuechips\"><button class=\"chip active\" data-route=\"all\">客户全部订单</button><button class=\"chip\" data-route=\"自提\">自提</button><button class=\"chip\" data-route=\"邮寄\">邮寄</button><button class=\"chip\" data-route=\"三谷\">三谷</button><button class=\"chip\" data-route=\"95008\">95008</button></div><div class=\"note\">勾选商品旁的到货框即可登记到货。若原表写“到齐”，系统会预填为已到货；“差几个”、缺货或数量不明确的内容会要求人工复核。</div><div class=\"tablewrap\"><table><thead><tr><th>到货</th><th>订单 / 来源</th><th>商品明细</th><th>数量</th><th>原订单状态</th><th>金额</th></tr></thead><tbody id=\"itemRows\"></tbody></table></div><div id=\"readyNotice\"></div></div></section></div><div class=\"foot\">订单导入与到货登记 · 文件仅在本机浏览器解析 · 尚未连接长期云端数据库</div></main><div class=\"toast\" id=\"toast\"></div>\n<script src=\"./workbook-reader.js\"></script><script src=\"./orders.js\"></script></body></html>\n","type":"text/html;charset=utf-8"},"/orders.js":{"text":"(()=>{\nconst $=id=>document.getElementById(id),str=v=>String(v??'').trim(),money=n=>n===null||n===undefined||n===''?'—':Number.isFinite(Number(n))?'$'+Number(n).toFixed(2):'—',escapeHtml=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst STORE='yiyi-orders-v1';let orders=[],groups=[],selected='',routeView='all',batchHashes=new Set();\nfunction toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4200)}\nfunction normalizeName(v){return str(v).toLocaleLowerCase().replace(/[\\s\\u3000]+/g,'')}\nfunction normalizePhone(v){return String(v||'').replace(/\\D/g,'').replace(/^1(?=\\d{10}$)/,'')}\nfunction parseCsv(text){const rows=[];let row=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='\"'&&text[i+1]==='\"'){value+='\"';i++}else if(c==='\"')quoted=false;else value+=c}else if(c==='\"')quoted=true;else if(c===','){row.push(value);value=''}else if(c==='\\n'||c==='\\r'){if(c==='\\r'&&text[i+1]==='\\n')i++;row.push(value);if(row.some(str))rows.push(row);row=[];value=''}else value+=c}row.push(value);if(row.some(str))rows.push(row);return [{name:'导入文件',rows}]}\nfunction colIndex(headers,aliases){for(let i=0;i<headers.length;i++){const h=str(headers[i]).toLowerCase().replace(/[\\s_\\-]/g,'');if(aliases.some(a=>h===a.toLowerCase().replace(/[\\s_\\-]/g,'')))return i}return -1}\nfunction value(row,headers,aliases,fallback=-1){const i=colIndex(headers,aliases);return str(row[i>=0?i:fallback])}\nfunction parseQuantity(text){const matches=[...String(text).matchAll(/(?:[xX×＊*]\\s*|数量\\s*[:：]?\\s*)(\\d{1,3})(?=\\s|$|[，,；;。到缺自寄发）\\]])/g)];if(matches.length===1)return Number(matches[0][1]);const m=String(text).match(/(?:^|[（(,，\\s])(\\d{1,3})\\s*(?:件|个|双|条|盒|套)(?:$|[，,；;。)）\\s])/);return m?Number(m[1]):null}\nfunction splitItems(content){const s=String(content||'').replace(/\\r/g,'').trim();if(!s)return[];let lines=s.split(/\\n+/).map(str).filter(Boolean);if(lines.length===1&&/[，,；;]/.test(lines[0]))lines=lines[0].split(/[，,；;]+/).map(str).filter(Boolean);return lines.map((raw,i)=>({id:String(i),raw,qty:parseQuantity(raw),status:/缺货|未到货|没到货|无货/.test(raw)?'missing':/到货/.test(raw)?'arrived':null}))}\nfunction routeFor(sheet,row){const s=String(sheet||'');if(s.includes('95008'))return'95008';if(s.includes('三谷'))return'三谷';if(s.includes('邮寄')||s.includes('郵寄'))return'邮寄';if(s.includes('自提')||s.includes('自取'))return'自提';const explicit=row.map(str).find(v=>/^(邮寄|郵寄|自提|自取)$/.test(v));return explicit==='郵寄'?'邮寄':explicit==='自取'?'自提':explicit||'待分类'}\nfunction mapWorkbook(sheets,fileHash){const result=[],ignored=[],issues=[];for(const sheet of sheets){if(/shippo/i.test(sheet.name)){ignored.push(sheet.name);continue}const rows=sheet.rows||[];const headIdx=rows.findIndex(r=>r&&r.some(str));if(headIdx<0)continue;const headers=rows[headIdx];for(let ix=headIdx+1;ix<rows.length;ix++){const r=rows[ix];if(!r||!r.some(str))continue;const name=value(r,headers,['姓名','客户姓名','客户','微信名','customer','customer_name'],3);const content=value(r,headers,['内容','商品内容','商品明细','商品','items','description'],4);if(!name&&!content)continue;const rawAmount=value(r,headers,['总价','金额','订单金额','total','amount'],5);const amountNum=Number(String(rawAmount).replace(/[$,]/g,''));const arrival=value(r,headers,['到货情况','到货状态','arrival','arrival_status'],0);const payment=value(r,headers,['付款情况','付款状态','payment','payment_status'],1);const orderNumber=value(r,headers,['序号','订单号','订单编号','order_id','order_number'],2);const tail=r.slice(6).map(str).filter(Boolean);const phoneCell=tail.find(x=>/(?:\\+?1[\\s().-]*)?\\(?\\d{3}\\)?[\\s().-]*\\d{3}[\\s().-]*\\d{4}/.test(x))||'';const phoneMatch=phoneCell.match(/(?:\\+?1[\\s().-]*)?\\(?\\d{3}\\)?[\\s().-]*\\d{3}[\\s().-]*\\d{4}/);const phone=phoneMatch?phoneMatch[0]:'';const zip=(tail.join(' ').match(/\\b\\d{5}(?:-\\d{4})?\\b/)||[])[0]||'';const address=tail.find(x=>/\\d+\\s+[^,]+(?:street|st\\.?|road|rd\\.?|avenue|ave\\.?|drive|dr\\.?|court|ct\\.?|lane|ln\\.?|boulevard|blvd\\.?|way|terrace|pl\\.?)/i.test(x))||'';const items=splitItems(content);const fullArrival=/到齐|全部到|全到/.test(arrival);for(const item of items){if(!item.status)item.status=fullArrival?'arrived':'waiting'}const route=routeFor(sheet.name,r);const sourceRow=ix+1;const order={id:fileHash+'|'+sheet.name+'|'+sourceRow,sourceSheet:sheet.name,sourceRow,route,name,phone,phoneKey:normalizePhone(phone),zip,address,orderNumber,content,amount:rawAmount&&Number.isFinite(amountNum)?amountNum:null,amountRaw:rawAmount,arrivalOriginal:arrival,paymentOriginal:payment,items,issues:[]};if(!name)order.issues.push('缺少客户姓名');if(!content)order.issues.push('商品内容为空');if(rawAmount&&!Number.isFinite(amountNum))order.issues.push('订单金额无法识别');if(!rawAmount)order.issues.push('缺少订单金额');if(items.some(x=>x.qty===null))order.issues.push('有商品数量无法自动识别');if(/差|缺|未到/.test(arrival)||items.some(x=>x.status==='missing'))order.issues.push('原表显示部分到货或缺货');if(!phone)order.issues.push('未识别到电话号码，客户匹配需复核');result.push(order)}}\n  const byName=new Map();for(const o of result){const k=normalizeName(o.name)||o.id;if(!byName.has(k))byName.set(k,[]);byName.get(k).push(o)}\n  for(const [key,list] of byName){const g={key,orders:list,phones:[...new Set(list.map(o=>o.phoneKey).filter(Boolean))]};if(g.phones.length>1){for(const o of list)o.issues.push('同名订单存在多个电话号码，请确认是否同一客户')} }\n  return{orders:result,ignored,issues};\n}\nfunction allItems(g){return g.orders.flatMap(o=>o.items.map(i=>({order:o,item:i})))}\nfunction arrived(g){const items=allItems(g);return items.length>0&&items.every(x=>x.item.status==='arrived')}\nfunction needsReview(g){return g.fulfillment==='待确认' || g.fulfillment==='待分类' || g.orders.some(o=>o.issues.length>0)}\nfunction getGroups(){const m=new Map();for(const o of orders){const k=normalizeName(o.name)||o.id;if(!m.has(k))m.set(k,{key:k,name:o.name,orders:[],routes:new Set(),phones:new Set()});const g=m.get(k);g.orders.push(o);g.routes.add(o.route);if(o.phoneKey)g.phones.add(o.phoneKey)}for(const g of m.values()){const hasPickup=g.orders.some(o=>/自提|自取/.test(o.content));const hasMail=g.orders.some(o=>/送货费/.test(o.content));if(hasPickup&&hasMail){g.fulfillment='待确认';for(const o of g.orders)if(!o.issues.includes('同一客户的订单同时出现“自提”和“送货费”，请确认配送方式'))o.issues.push('同一客户的订单同时出现“自提”和“送货费”，请确认配送方式')}else if(hasPickup)g.fulfillment='自提';else if(hasMail)g.fulfillment='邮寄';else if(g.routes.has('自提'))g.fulfillment='自提';else if(g.routes.has('邮寄'))g.fulfillment='邮寄';else g.fulfillment='待分类'}return [...m.values()].sort((a,b)=>a.name.localeCompare(b.name,'zh-CN'))}\nfunction persist(){try{localStorage.setItem(STORE,JSON.stringify({orders,batchHashes:[...batchHashes]}));return true}catch(e){toast('本机存储空间不足，先导出订单备份后再继续。');return false}}\nfunction restore(){try{const saved=JSON.parse(localStorage.getItem(STORE)||'{}');orders=Array.isArray(saved.orders)?saved.orders:[];batchHashes=new Set(saved.batchHashes||[]);groups=getGroups()}catch{orders=[];groups=[];batchHashes=new Set()}}\nfunction totals(){groups=getGroups();$('nCustomers').textContent=groups.length;$('nOrders').textContent=orders.length;$('nArrived').textContent=groups.filter(arrived).length;$('nReview').textContent=groups.filter(needsReview).length}\nfunction updateList(){totals();const q=$('search').value.toLocaleLowerCase();const filter=$('filter').value;let list=groups.filter(g=>[g.name,...g.orders.map(o=>o.phone+' '+o.orderNumber)].join(' ').toLocaleLowerCase().includes(q));if(filter==='ready')list=list.filter(arrived);if(filter==='waiting')list=list.filter(g=>!arrived(g));if(filter==='review')list=list.filter(needsReview);if(filter==='pickup')list=list.filter(g=>g.fulfillment==='自提');if(filter==='mail')list=list.filter(g=>g.fulfillment==='邮寄');if(filter==='tri')list=list.filter(g=>g.routes.has('三谷'));if(filter==='zip95008')list=list.filter(g=>g.routes.has('95008'));if(filter==='unassigned')list=list.filter(g=>g.fulfillment==='待确认'||g.fulfillment==='待分类');$('customerList').innerHTML=list.length?list.map(g=>`<div class=\"customer ${g.key===selected?'active':''}\" data-key=\"${escapeHtml(g.key)}\"><div><b>${escapeHtml(g.name)}</b><small>${g.orders.length} 笔订单 · ${allItems(g).length} 条商品明细</small></div><span class=\"badge ${needsReview(g)?'warn':arrived(g)?'ready':''}\">${g.fulfillment==='待确认'?'配送冲突':g.fulfillment==='待分类'?'待分类':arrived(g)?'全部到齐':needsReview(g)?'待复核':'未到齐'}</span></div>`).join(''):'<div class=\"empty\">没有符合条件的客户</div>';document.querySelectorAll('.customer').forEach(el=>el.onclick=()=>selectCustomer(el.dataset.key))}\nfunction selectCustomer(key){selected=key;routeView='all';document.querySelectorAll('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route==='all'));drawDetail();updateList()}\nfunction drawDetail(){const g=groups.find(x=>x.key===selected);if(!g){$('detail').hidden=true;$('detailEmpty').hidden=false;return}$('detail').hidden=false;$('detailEmpty').hidden=true;$('customerTitle').textContent=g.name;$('customerSub').textContent=`${g.orders.length} 笔订单 · ${allItems(g).length} 条商品明细`;$('customerStatus').textContent=g.fulfillment==='待确认'?'配送方式冲突':g.fulfillment==='待分类'?'配送方式待确认':arrived(g)?'全部到齐 · 可处理':needsReview(g)?'待复核':'等待到货';$('customerStatus').className='badge '+(g.fulfillment==='待确认'||g.fulfillment==='待分类'||needsReview(g)?'warn':arrived(g)?'ready':'');const phoneText=[...g.phones].length>0?[...new Set(g.orders.map(o=>o.phone).filter(Boolean))].join(' / '):'未识别';const moneyTotal=g.orders.reduce((sum,o)=>sum+(o.amount||0),0);const regionText=[...new Set(g.orders.map(o=>o.sourceSheet).filter(x=>x==='三谷'||x==='95008'))].join('、')||'未标记';$('customerMeta').innerHTML=`<span>配送分类：${escapeHtml(g.fulfillment)}</span><span>地区标签：${escapeHtml(regionText)}</span><span>电话：${escapeHtml(phoneText)}</span><span>订单总额：${money(moneyTotal)}</span>`;const samePhone=groups.filter(other=>other.key!==g.key&&other.orders.some(o=>o.phoneKey&&g.phones.has(o.phoneKey)));$('possibleMatch').innerHTML=samePhone.length?`<div class=\"note\">可能存在同一电话下的其他姓名：${samePhone.map(x=>escapeHtml(x.name)).join('、')}。请确认后再合并，系统暂不自动合并。</div>`:'';const list=g.orders.filter(o=>routeView==='all'||(routeView==='自提'&&g.fulfillment==='自提')||(routeView==='邮寄'&&g.fulfillment==='邮寄')||((routeView==='三谷'||routeView==='95008')&&o.route===routeView));$('itemRows').innerHTML=list.map(o=>o.items.map((item,index)=>`<tr><td><div class=\"itemstatus\"><input class=\"check\" type=\"checkbox\" data-order=\"${escapeHtml(o.id)}\" data-item=\"${escapeHtml(item.id)}\" ${item.status==='arrived'?'checked':''} aria-label=\"${escapeHtml(item.raw)} 到货\"><span class=\"statuslabel\">${item.status==='arrived'?'已到货':item.status==='missing'?'缺货':'未到货'}</span></div></td><td><b>${escapeHtml(o.orderNumber||'无订单号')}</b><br><span class=\"route-label\">${escapeHtml(o.sourceSheet)} · 第 ${o.sourceRow} 行</span></td><td class=\"product\">${escapeHtml(item.raw)}${o.issues.includes('有商品数量无法自动识别')&&item.qty===null?' <span class=\"badge warn\">数量待核实</span>':''}</td><td>${item.qty??'待核实'}</td><td>${escapeHtml(o.arrivalOriginal||'未填写')}<br><span class=\"route-label\">${escapeHtml(o.paymentOriginal||'付款待确认')}</span></td><td class=\"money\">${index===0?money(o.amount):'—'}</td></tr>`).join('')).join('');document.querySelectorAll('[data-order][data-item]').forEach(box=>box.onchange=()=>{const o=orders.find(x=>x.id===box.dataset.order),item=o?.items.find(x=>x.id===box.dataset.item);if(!item)return;item.status=box.checked?'arrived':'waiting';persist();drawDetail();updateList()});if(arrived(g)){const message=g.fulfillment==='自提'?'全部到齐 · 可放入自提区':g.fulfillment==='邮寄'?'全部到齐 · 已进入待打包队列':'全部到齐 · 请先确认自提或邮寄';const cls=g.fulfillment==='待确认'||g.fulfillment==='待分类'?'note':'success';$('readyNotice').innerHTML=`<div class=\"${cls}\"><b>${message}</b><br>该客户目前显示的所有商品都已标记到货。${g.fulfillment==='自提'?'请移至自提区。':g.fulfillment==='邮寄'?'可进入打包流程。':'内容中未能唯一识别配送方式，请检查“自提”或“送货费”标记。'}</div>`}else{$('readyNotice').innerHTML=''} }\nasync function importFile(file){if(!file)return;try{const bytes=await file.arrayBuffer();const hash=await crypto.subtle.digest('SHA-256',bytes);const fileHash=[...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('');if(batchHashes.has(fileHash)){toast('这份文件已经导入过了，没有重复添加。');return}let sheets;if(/\\.csv$/i.test(file.name)){sheets=parseCsv(new TextDecoder().decode(bytes))}else if(/\\.xlsx$/i.test(file.name)){sheets=await readOrderWorkbook(bytes)}else throw Error('请使用 .xlsx 或 .csv 文件');const parsed=mapWorkbook(sheets,fileHash);if(!parsed.orders.length)throw Error('没有识别到订单行，请检查工作表和表头');if($('importMode').value==='replace'){if(!confirm('替换本机当前订单？当前数据会被本次文件取代。建议先导出备份。'))return;orders=[];batchHashes.clear()}const sig=o=>[normalizeName(o.name),o.route,str(o.content).toLowerCase().replace(/[\\s\\u3000]+/g,''),o.amountRaw].join('|');const existing=new Set(orders.map(sig)),seen=new Set();for(const o of parsed.orders){const s=sig(o);if(existing.has(s)||seen.has(s))o.issues.push('与另一笔订单的客户、商品和金额相同，可能重复导入，请核对原始订单号');seen.add(s)}const newRows=parsed.orders.filter(n=>!orders.some(old=>old.id===n.id));orders.push(...newRows);batchHashes.add(fileHash);persist();$('filename').textContent=file.name;selected='';drawDetail();updateList();const ignored=parsed.ignored.length?` 已跳过非订单页：${parsed.ignored.join('、')}。`:'';$('importResult').innerHTML=`<div class=\"success\">导入 ${newRows.length} 笔订单，识别 ${new Set(newRows.map(o=>normalizeName(o.name))).size} 位客户。${ignored}${newRows.filter(o=>o.issues.length).length} 笔订单需要人工复核。</div>`;toast(`已导入 ${newRows.length} 笔订单`)}catch(e){toast('导入失败：'+e.message)}finally{$('file').value=''}}\nfunction csvCell(v){return'\"'+String(v??'').replace(/\"/g,'\"\"')+'\"'}\nfunction exportCsv(){const header=['客户','电话','来源工作表','订单号','来源行','商品明细','数量','到货状态','原到货状态','原付款状态','订单金额','配送分类','邮编','地址','复核项'];const rows=[header];for(const o of orders)for(const item of o.items)rows.push([o.name,o.phone,o.sourceSheet,o.orderNumber,o.sourceRow,item.raw,item.qty??'',item.status,o.arrivalOriginal,o.paymentOriginal,o.amount??o.amountRaw,o.route,o.zip,o.address,o.issues.join('；')]);const csv='\\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\\r\\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='yiyi-orders-backup-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}\n$('file').onchange=e=>importFile(e.target.files?.[0]);$('search').oninput=updateList;$('filter').onchange=updateList;$('export').onclick=exportCsv;$('reset').onclick=()=>{if(!confirm('清空这台电脑浏览器中的所有本机订单数据？此操作不会删除原始 Excel，但清空后需从备份或 Excel 重新导入。'))return;orders=[];groups=[];batchHashes.clear();selected='';localStorage.removeItem(STORE);$('filename').textContent='尚未导入文件';$('importResult').replaceChildren();drawDetail();updateList();toast('本机订单数据已清空')};document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{routeView=b.dataset.route;document.querySelectorAll('[data-route]').forEach(x=>x.classList.toggle('active',x===b));drawDetail()});restore();updateList();\n})();\n","type":"application/javascript;charset=utf-8"},"/workbook-reader.js":{"text":"// Small read-only XLSX reader for standard worksheet values. No formulas are evaluated.\nasync function readOrderWorkbook(buffer){\n  const data=new Uint8Array(buffer),view=new DataView(buffer),u16=p=>view.getUint16(p,true),u32=p=>view.getUint32(p,true);\n  let end=-1;for(let p=data.length-22;p>=Math.max(0,data.length-65558);p--){if(u32(p)===0x06054b50){end=p;break}}\n  if(end<0)throw Error('这不是有效的 .xlsx 文件');\n  const files=new Map();let pos=u32(end+16),total=u16(end+10);\n  for(let i=0;i<total;i++){if(u32(pos)!==0x02014b50)throw Error('Excel 压缩包目录无效');const method=u16(pos+10),compressed=u32(pos+20),nameLen=u16(pos+28),extra=u16(pos+30),comment=u16(pos+32),local=u32(pos+42),name=new TextDecoder().decode(data.slice(pos+46,pos+46+nameLen));files.set(name,{method,compressed,local});pos+=46+nameLen+extra+comment}\n  async function content(path){const f=files.get(path);if(!f)throw Error('Excel 文件缺少组件：'+path);const start=f.local+30+u16(f.local+26)+u16(f.local+28),bytes=data.slice(start,start+f.compressed);if(f.method===0)return new TextDecoder().decode(bytes);if(f.method!==8)throw Error('暂不支持此 Excel 压缩格式');const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate-raw'));return new TextDecoder().decode(await new Response(stream).arrayBuffer())}\n  const xml=s=>{const d=new DOMParser().parseFromString(s,'application/xml');if(d.querySelector('parsererror'))throw Error('无法读取 Excel XML');return d};\n  const all=(node,name)=>Array.from(node.getElementsByTagName('*')).filter(e=>e.localName===name),child=(node,name)=>Array.from(node?.children||[]).find(e=>e.localName===name);\n  const workbook=xml(await content('xl/workbook.xml')),rels=xml(await content('xl/_rels/workbook.xml.rels'));\n  let strings=[];if(files.has('xl/sharedStrings.xml')){const s=xml(await content('xl/sharedStrings.xml'));strings=all(s,'si').map(si=>all(si,'t').map(t=>t.textContent).join(''))}\n  const sheets=all(workbook,'sheet').map(s=>{const id=s.getAttribute('r:id')||s.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id');const rel=all(rels,'Relationship').find(r=>r.getAttribute('Id')===id);if(!rel)return null;let target=rel.getAttribute('Target').replace(/^\\/+/, '').replace(/^\\.\\//,'');let path=target.startsWith('xl/')?target:'xl/'+target;return {name:s.getAttribute('name')||'',path}}).filter(Boolean);\n  async function readSheet(sheet){const doc=xml(await content(sheet.path)),rows=[];for(const r of all(doc,'row')){const rowNum=Number(r.getAttribute('r'));if(!rowNum||rowNum>100000)continue;const cells=[];for(const c of Array.from(r.children).filter(e=>e.localName==='c')){const ref=c.getAttribute('r')||'',letters=(ref.match(/^[A-Z]+/)||[])[0];if(!letters)continue;let col=0;for(const letter of letters)col=col*26+letter.charCodeAt(0)-64;col--;if(col>60)continue;const type=c.getAttribute('t'),v=child(c,'v'),inline=child(c,'is');let value=v?.textContent??'';if(type==='s')value=strings[Number(value)]??'';else if(type==='inlineStr')value=all(inline,'t').map(t=>t.textContent).join('');else if(type==='b')value=value==='1';else if(type!=='str'&&type!=='e'&&value!==''&&!Number.isNaN(Number(value)))value=Number(value);cells[col]=value}rows[rowNum-1]=cells}return rows}\n  const out=[];for(const s of sheets)out.push({...s,rows:await readSheet(s)});return out;\n}\n","type":"application/javascript;charset=utf-8"},"/shipping.html":{"text":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Yiyi Shipping Assistant — 邮寄</title>\n<style>\n:root{font-family:Inter,system-ui,sans-serif;color:#17353b;background:#f4f7f7}*{box-sizing:border-box}body{margin:0}header{background:#123c3e;color:white;padding:20px 28px;display:flex;justify-content:space-between;align-items:center}h1{font-size:23px;margin:0}h2{font-size:22px;margin:0 0 5px}h3{font-size:16px;margin:0 0 12px}.muted,small{font-size:12px;color:#77898c}.shell{max-width:1330px;margin:22px auto;padding:0 16px}.grid{display:grid;grid-template-columns:330px 1fr;gap:17px}.card{background:white;padding:18px;border:1px solid #dce6e7;border-radius:14px;margin-bottom:16px;box-shadow:0 2px 16px #123c3e09}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:16px}.stat{background:white;border:1px solid #e1e8e9;border-radius:11px;padding:14px}.stat b{font-size:24px;display:block}.stat small{display:block}button{font:inherit;border:0;background:#156b5a;color:white;border-radius:9px;padding:10px 13px;font-size:13px;font-weight:700;cursor:pointer}button.alt{background:#e7efef;color:#31545b}button:disabled{opacity:.5}input,select,textarea{font:inherit;color:#17353b;border:1px solid #cfdddd;border-radius:8px;padding:10px;width:100%}input[type=checkbox]{width:17px;height:17px;accent-color:#16715b}textarea{resize:vertical;min-height:76px}label{display:block;color:#587075;font-size:12px;font-weight:700;margin:10px 0 6px}.drop{border:1px dashed #85b5ac;background:#f4faf8;border-radius:10px;padding:17px;text-align:center}.drop label{cursor:pointer;color:#116b58;font-size:14px}.drop input{display:none}.note{border:1px solid #f2ddaf;background:#fff8e9;color:#795d20;border-radius:9px;font-size:12px;line-height:1.5;padding:10px;margin:12px 0}.pill{font-size:11px;font-weight:700;border-radius:20px;padding:6px 10px;background:#d9f3e5;color:#17694c;display:inline-block}.pill.warn{background:#fff0ce;color:#825d19}.pill.gray{background:#e7eeee;color:#5e7379}.row{display:flex;justify-content:space-between;align-items:center;gap:10px}.buttons{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.customer{border:1px solid #e3ebeb;border-radius:9px;margin:7px 0;padding:11px;cursor:pointer;display:flex;justify-content:space-between;gap:10px}.customer.active,.customer:hover{background:#e9f6f1;border-color:#6fb6a3}.customer b{font-size:13px}.customer small{display:block}.list{max-height:590px;overflow:auto}.tabs{display:flex;flex-wrap:wrap;gap:7px;margin:10px 0 16px}.tabs button{background:#eaf0f0;color:#4c6b70;border-radius:20px}.tabs button.active{background:#166c5b;color:white}table{border-collapse:collapse;width:100%;font-size:12px}th,td{padding:9px 7px;border-bottom:1px solid #e7eeee;text-align:left;vertical-align:top}th{color:#75898e;font-size:11px}td.item{line-height:1.5;word-break:break-word}.right{text-align:right}.flag{border:1px solid #edd7af;background:#fff9ee;border-radius:9px;padding:10px;margin:7px 0;font-size:12px}.flag label{display:flex;gap:9px;align-items:center;color:#46595b;margin:0}.flag input{flex:none}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.three{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.line{display:flex;justify-content:space-between;border-bottom:1px solid #edf1f1;padding:9px 0}.line.big{font-size:20px;font-weight:800;border:0}.divider{height:1px;background:#e3ebeb;margin:18px 0}.empty{text-align:center;padding:35px 15px;color:#8a999a;background:#f8faf9;border-radius:10px}.hidden{display:none!important}.footer{font-size:12px;color:#85999b;margin:20px 0 35px}#toast{position:fixed;bottom:20px;right:20px;background:#123d3e;color:white;padding:13px 16px;border-radius:10px;display:none;max-width:340px;box-shadow:0 8px 25px #0002}@media(max-width:850px){.grid{grid-template-columns:1fr}.list{max-height:300px}}@media(max-width:520px){.stats{grid-template-columns:repeat(2,1fr)}.two,.three{grid-template-columns:1fr}header{padding:16px}.shell{padding:0 9px}}\n</style></head><body>\n<header><div><h1>📦 Yiyi Shipping Assistant</h1><small style=\"color:#c3d7d7\">一一妈咪好物团 · 邮寄 Packing Station</small></div><nav style=\"display:flex;gap:8px;align-items:center\"><a href=\"./orders.html\" style=\"color:#d9ebe8;text-decoration:none;padding:8px 10px;border-radius:8px;font-size:12px\">订单与到货</a><a href=\"./shipping.html\" style=\"color:#145d50;background:#fff;text-decoration:none;padding:8px 10px;border-radius:8px;font-size:12px;font-weight:700\">打包与 Shippo</a><span class=\"pill\">Private MVP</span></nav></header>\n<main class=\"shell\"><div class=\"row\" style=\"margin-bottom:18px\"><div><h2>Shipping queue</h2><small>Source-matched customer orders, item checks, payment review</small></div><button class=\"alt\" id=\"export\">Export prepared log</button></div>\n<div class=\"grid\"><aside><div class=\"card\"><h3>1. Import master workbook</h3><div class=\"drop\"><label for=\"file\">⬆ Upload Excel or CSV</label><input id=\"file\" type=\"file\" accept=\".xlsx,.xls,.csv\"><small id=\"filename\">Only the 邮寄 sheet will be imported</small></div><div class=\"note\">This prototype processes data locally in your browser session. It does not send customer information to Shippo, WeChat or AI. Do not rely on it as a permanent database.</div><div class=\"buttons\"><button class=\"alt\" id=\"demo\">Load demonstration</button><button class=\"alt\" id=\"clear\">Clear session</button></div></div><div class=\"card\"><h3>2. Customer queue</h3><label>Search name or source row</label><input id=\"search\" placeholder=\"Search in English / 中文\"><label>Queue filter</label><select id=\"filter\"><option value=\"all\">All imported customers</option><option value=\"review\">Needs review</option><option value=\"ready\">Marked fully arrived</option><option value=\"verified\">Packing verified</option></select><div id=\"customerList\" class=\"list\"><div class=\"empty\">Import to begin</div></div></div></aside>\n<section><div class=\"stats\"><div class=\"stat\"><b id=\"countRows\">0</b><small>Order rows</small></div><div class=\"stat\"><b id=\"countCustomers\">0</b><small>Customers</small></div><div class=\"stat\"><b id=\"countReview\">0</b><small>Need review</small></div><div class=\"stat\"><b id=\"countVerified\">0</b><small>Verified bags</small></div></div>\n<div class=\"card\"><div class=\"row\"><h3 id=\"title\">Select a customer</h3><span class=\"pill gray\" id=\"status\">Waiting</span></div><div id=\"empty\" class=\"empty\">Choose a customer from the left. Source row numbers will be retained.</div>\n<div id=\"detail\" class=\"hidden\"><div class=\"tabs\"><button id=\"tabItems\" class=\"active\">Packing checklist</button><button id=\"tabSource\">Original order rows</button><button id=\"tabReview\">Exceptions & payment</button></div>\n<div id=\"itemsView\"><div class=\"note\" id=\"quantityNote\">Quantities are provisional until checked against physical items.</div><table><thead><tr><th>✓</th><th>Product from 内容 column</th><th class=\"right\">Qty</th><th>Row</th></tr></thead><tbody id=\"items\"></tbody></table><div class=\"buttons\"><button class=\"alt\" id=\"checkAll\">Check all</button><button id=\"confirmPacking\">Confirm packed items</button></div></div>\n<div id=\"sourceView\" class=\"hidden\"><div class=\"note\">The amount in Excel column F is authoritative per order row; product-level amounts are not present and will not be invented.</div><table><thead><tr><th>Row</th><th>Arrival</th><th>Payment</th><th class=\"right\">Amount</th><th>Description</th></tr></thead><tbody id=\"sourceRows\"></tbody></table></div>\n<div id=\"reviewView\" class=\"hidden\"><div class=\"note\" id=\"reviewNote\"></div><div id=\"flags\"></div><div class=\"divider\"></div><h3>Financial verification</h3><div class=\"two\"><div><div class=\"line\"><span>Source order total</span><b id=\"merch\">$0.00</b></div><div class=\"line\"><span>Adjustment / credit</span><b id=\"adjustmentDisplay\">$0.00</b></div><div class=\"line\"><span>Customer shipping fee</span><b id=\"feeDisplay\">$7.00</b></div><div class=\"line big\"><span>Provisional due</span><b id=\"due\">$0.00</b></div></div><div><label>Manual adjustment ($; negative = credit)</label><input id=\"adjustment\" type=\"number\" step=\".01\" value=\"0\"><label>Customer shipping fee ($)</label><input id=\"fee\" type=\"number\" step=\".01\" value=\"7\"><label>Payment status</label><select id=\"payment\"><option value=\"Unconfirmed\">Unconfirmed</option><option value=\"Confirmed by staff\">Confirmed by staff</option><option value=\"Partial\">Partial payment</option></select></div></div><label>Reviewer notes</label><textarea id=\"notes\" placeholder=\"Explain refund or credit and any quantity differences\"></textarea><div class=\"buttons\"><button id=\"reviewDone\">Acknowledge review flags</button></div></div>\n<div class=\"divider\"></div><h3>3. Package information</h3><div class=\"two\"><div><label>Recipient</label><input id=\"recipient\"></div><div><label>Phone</label><input id=\"phone\"></div></div><label>Address candidate (must be checked)</label><textarea id=\"address\"></textarea><div class=\"three\"><div><label>Weight (kg)</label><input id=\"weight\" type=\"number\" min=\"0\" step=\".01\"></div><div><label>Length (in)</label><input id=\"length\" type=\"number\" value=\"10\"></div><div><label>Width (in)</label><input id=\"width\" type=\"number\" value=\"8\"></div></div><div class=\"two\"><div><label>Height (in)</label><input id=\"height\" type=\"number\" value=\"4\"></div><div><label>Carrier preference — not connected</label><select id=\"carrier\"><option>Compare USPS / UPS</option><option>USPS</option><option>UPS</option></select></div></div><div class=\"buttons\"><button id=\"prepare\">Prepare draft (no shipping)</button><button class=\"alt\" id=\"copy\">Copy WeChat text</button></div><div id=\"draftBox\" class=\"hidden\"><label>Customer message — for manual review and sending only</label><textarea id=\"draft\" rows=\"9\" style=\"min-height:210px\"></textarea></div></div></div></section></div><div class=\"footer\">No labels purchased · No messages sent · No payments processed · No live Shippo integration</div></main><div id=\"toast\"></div>\n<main class=\"shell\"><section class=\"card\" id=\"shippoPanel\"><div class=\"row\"><h3>4. Shippo sandbox integration</h3><span id=\"shippoStatus\" class=\"pill warn\">Checking test connection…</span></div><div class=\"note\">Test mode only. Confirm US addresses before quoting. Clicking “Get test rates” sends entered address and package details to Shippo. This integration rejects all live API keys and cannot buy real postage.</div>\n<div class=\"two\"><div><h3>Ship from</h3><label>Sender name</label><input id=\"fromName\" placeholder=\"Business / sender\"><label>Street address</label><input id=\"fromStreet\"><label>City</label><input id=\"fromCity\"><div class=\"two\"><div><label>State</label><input id=\"fromState\" placeholder=\"CA\"></div><div><label>ZIP</label><input id=\"fromZip\"></div></div><label>Phone (optional)</label><input id=\"fromPhone\"></div><div><h3>Ship to</h3><label>Recipient name</label><input id=\"toName\"><label>Street address</label><input id=\"toStreet\"><label>City</label><input id=\"toCity\"><div class=\"two\"><div><label>State</label><input id=\"toState\" placeholder=\"CA\"></div><div><label>ZIP</label><input id=\"toZip\"></div></div><label>Phone (optional)</label><input id=\"toPhone\"></div></div>\n<div class=\"buttons\"><button id=\"getRates\">Get test rates</button><button id=\"resetRates\" class=\"alt\">Clear test quote</button></div><div id=\"rateError\" class=\"note hidden\"></div><div id=\"rates\" class=\"hidden\"><h3>USPS and UPS test rates</h3><div id=\"rateChoices\"></div><div class=\"buttons\"><button id=\"createTestLabel\">Generate selected TEST label</button></div></div><div id=\"testLabel\" class=\"hidden note\"></div></section></main>\n<script src=\"./xlsx-reader.js\"></script><script src=\"./shipping.js\"></script><script src=\"./shippo-client.js\"></script></body></html>\n","type":"text/html;charset=utf-8"},"/shipping.js":{"text":"const $=id=>document.getElementById(id),str=v=>String(v??'').trim(),num=v=>{const n=Number(str(v).replace(/[$,]/g,''));return Number.isFinite(n)?n:0},usd=n=>'$'+num(n).toFixed(2),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nlet orders=[],customers=[],selected='',states=new Map(),logs=[];function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').style.display='none',3900)}\nfunction csv(text){let rows=[],r=[],v='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='\"'&&text[i+1]==='\"'){v+='\"';i++}else if(c==='\"')quoted=false;else v+=c}else if(c==='\"')quoted=true;else if(c===','){r.push(v);v=''}else if(c==='\\r'||c==='\\n'){if(c==='\\r'&&text[i+1]==='\\n')i++;r.push(v);if(r.some(str))rows.push(r);r=[];v=''}else v+=c}r.push(v);if(r.some(str))rows.push(r);return rows}\nfunction findPhone(s){const m=String(s||'').match(/(?:\\+?1[\\s().-]*)?\\(?\\d{3}\\)?[\\s().-]*\\d{3}[\\s().-]*\\d{4}/);return m?m[0]:''}\nfunction rowMap(r,i){let v=j=>r[j]??'',tail=r.slice(7,13).map(str).filter(Boolean),phones=tail.map(findPhone).filter(Boolean),address=tail.find(x=>!findPhone(x)&&(/\\d+\\s+[^\\n]+(?:st|street|rd|road|ave|avenue|dr|drive|ct|court|ln|lane|blvd|way|loop|terrace|pl|place)\\b/i.test(x)||/\\d{5}/.test(x)))||'',amount=typeof v(5)==='number'?v(5):Number(str(v(5)).replace(/[$,]/g,''));return {row:i+2,name:str(v(3)),arrival:str(v(0)),payment:str(v(1)),number:str(v(2)),content:str(v(4)),amount,amountValid:Number.isFinite(amount)&&v(5)!=='',originalAmount:str(v(5)),notes:str(v(6)),recipient:tail.find(x=>x&&!findPhone(x)&&x.length<50&&!/\\d{4}/.test(x))||str(v(3)),phone:phones[0]||'',address,tail}}\nfunction splitItems(text){let out=[],word='',depth=0;for(const c of String(text||'').replace(/\\r/g,'')){if('([（【'.includes(c))depth++;if(')]）】'.includes(c))depth=Math.max(0,depth-1);if((c==='\\n'||c==='，'||c===','||c==='；'||c===';')&&depth===0){if(str(word))out.push(str(word));word=''}else word+=c}if(str(word))out.push(str(word));return out}\nfunction parseItem(s,row){const patterns=[...s.matchAll(/(?:[xX×*＊]\\s*|数量\\s*[:：]?\\s*)(\\d{1,3})(?=\\s|$|[，,；;。到缺自寄发）)\\]])/g)];const qty=patterns.length===1?Number(patterns[0][1]):null,missing=/缺货|未到|没到|差\\d|还没/.test(s),uncertain=qty===null||/换|改成|退款|退\\d|加单|补寄|赠品|自提|邮寄/.test(s);return {text:s,qty,row:row.row,missing,uncertain}}\nfunction buildGroups(rows){const m=new Map();for(const r of rows){if(!r.name)continue;const key=r.name.toLocaleLowerCase();if(!m.has(key))m.set(key,{key,name:r.name,rows:[],items:[],issues:[]});const g=m.get(key);g.rows.push(r);for(const item of splitItems(r.content))g.items.push(parseItem(item,r))}return [...m.values()].map(g=>{let issues=[];if(g.rows.some(r=>!r.amountValid))issues.push('Missing or invalid source amount in column F');if(g.rows.some(r=>/差|缺|未到/.test(r.arrival)))issues.push('Arrival status indicates missing items');if(g.rows.some(r=>!/到齐|全到|全部到/.test(r.arrival)))issues.push('Some order rows are not explicitly marked fully received');if(g.items.some(i=>i.uncertain))issues.push('Product quantity or description needs confirmation');if(g.items.some(i=>i.missing))issues.push('Product notes indicate possibly missing stock');if(g.rows.some(r=>/退|退款|抵扣|余额|部分|补差|已付\\d/.test(r.payment+' '+r.notes)))issues.push('Refund / payment note needs manual interpretation');if(new Set(g.rows.map(r=>r.phone).filter(Boolean)).size>1)issues.push('Different phone numbers under the same customer name');if(!g.rows.some(r=>r.address))issues.push('No reliable street address recognized');g.issues=[...new Set(issues)];g.total=g.rows.reduce((a,r)=>a+(r.amountValid?r.amount:0),0);g.units=g.items.reduce((a,i)=>a+(i.qty||0),0);return g}).sort((a,b)=>a.name.localeCompare(b.name))}\nfunction state(g){if(!states.has(g.key))states.set(g.key,{reviewed:false,verified:false,checks:{},resolved:{},qtyOverride:{},adjustment:0,fee:7,payment:'Unconfirmed',notes:'',weight:'',length:10,width:8,height:4,recipient:g.rows.find(r=>r.recipient)?.recipient||g.name,phone:g.rows.find(r=>r.phone)?.phone||'',address:g.rows.find(r=>r.address)?.address||'',carrier:'Compare USPS / UPS',draft:''});return states.get(g.key)}\nfunction current(){return customers.find(g=>g.key===selected)}function reviewNeeded(g){return g.issues.length&&!state(g).reviewed}function ready(g){return g.rows.every(r=>r.amountValid&&/到齐|全到|全部到/.test(r.arrival))&&!g.items.some(i=>i.missing)}\nfunction updateList(){$('countRows').textContent=orders.length;$('countCustomers').textContent=customers.length;$('countReview').textContent=customers.filter(reviewNeeded).length;$('countVerified').textContent=customers.filter(g=>state(g).verified).length;const query=$('search').value.toLocaleLowerCase(),filter=$('filter').value;let visible=customers.filter(g=>g.name.toLocaleLowerCase().includes(query)||g.rows.some(r=>String(r.row).includes(query)));if(filter==='review')visible=visible.filter(reviewNeeded);if(filter==='ready')visible=visible.filter(ready);if(filter==='verified')visible=visible.filter(g=>state(g).verified);$('customerList').innerHTML=visible.length?visible.map(g=>'<div class=\"customer '+(g.key===selected?'active':'')+'\" data-name=\"'+esc(g.key)+'\"><div><b>'+esc(g.name)+'</b><small>'+g.rows.length+' order rows · '+g.units+' explicitly parsed units</small></div><span class=\"pill '+(reviewNeeded(g)?'warn':'gray')+'\">'+(reviewNeeded(g)?g.issues.length+' flags':state(g).verified?'Verified':'Queue')+'</span></div>').join(''):'<div class=\"empty\">No matching customers</div>';[...document.querySelectorAll('.customer')].forEach(el=>el.onclick=()=>choose(el.dataset.name))}\nfunction save(){const g=current();if(!g)return;const s=state(g);for(const id of ['recipient','phone','address','weight','length','width','height','carrier','payment','notes','draft'])s[id]=$(id).value;s.adjustment=num($('adjustment').value);s.fee=num($('fee').value)}\nfunction choose(key){save();selected=key;const g=current();if(!g)return;const s=state(g);$('empty').classList.add('hidden');$('detail').classList.remove('hidden');$('title').textContent=g.name+' · '+g.rows.length+' order rows';for(const id of ['recipient','phone','address','weight','length','width','height','carrier','payment','notes','draft'])$(id).value=s[id];$('adjustment').value=s.adjustment;$('fee').value=s.fee;$('draftBox').classList.toggle('hidden',!s.draft);draw();showTab('Items')}\nfunction draw(){const g=current();if(!g)return;const s=state(g);$('status').textContent=s.verified?'Packing verified':reviewNeeded(g)?'Review required':'Pending packing';$('status').className='pill '+(reviewNeeded(g)?'warn':s.verified?'':'gray');$('quantityNote').textContent=g.items.length+' parsed item lines · '+g.units+' explicitly parsed units · '+g.items.filter(i=>i.qty===null).length+' unknown quantities. Correct quantities where needed and verify physical products.';$('items').innerHTML=g.items.map((i,n)=>'<tr><td><input type=\"checkbox\" data-check=\"'+n+'\" '+(s.checks[n]?'checked':'')+'></td><td class=\"item\">'+esc(i.text)+(i.uncertain?' <span class=\"pill warn\">Quantity review</span>':'')+(i.missing?' <span class=\"pill warn\">Missing?</span>':'')+'</td><td class=\"right\"><input aria-label=\"Verified quantity\" type=\"number\" min=\"0\" step=\"1\" data-qty=\"'+n+'\" value=\"'+esc(s.qtyOverride[n]??i.qty??'')+'\" style=\"width:64px;padding:5px\" placeholder=\"?\"></td><td>#'+i.row+'</td></tr>').join('');$('items').querySelectorAll('[data-check]').forEach(el=>el.onchange=()=>{s.checks[el.dataset.check]=el.checked;s.verified=false;updateList()});$('items').querySelectorAll('[data-qty]').forEach(el=>el.onchange=()=>{s.qtyOverride[el.dataset.qty]=el.value;s.verified=false;updateList()});$('sourceRows').innerHTML=g.rows.map(r=>'<tr><td>#'+r.row+'</td><td>'+esc(r.arrival||'—')+'</td><td>'+esc(r.payment||'—')+'</td><td class=\"right\">'+(r.amountValid?usd(r.amount):'Review')+'</td><td class=\"item\">'+esc(r.content)+'</td></tr>').join('');$('reviewNote').textContent=g.issues.length?g.issues.length+' exceptions automatically flagged. Acknowledgment does not change underlying Excel values.':'No automatic exception flags; still verify shipment and charges.';$('flags').innerHTML=g.issues.map((t,n)=>'<div class=\"flag\"><label><input type=\"checkbox\" data-issue=\"'+n+'\" '+(s.resolved[n]?'checked':'')+'>'+esc(t)+'</label></div>').join('');$('flags').querySelectorAll('[data-issue]').forEach(el=>el.onchange=()=>{s.resolved[el.dataset.issue]=el.checked;s.reviewed=false;updateList()});totals();updateList()}\nfunction totals(){const g=current();if(!g)return;$('merch').textContent=usd(g.total);$('adjustmentDisplay').textContent=usd($('adjustment').value);$('feeDisplay').textContent=usd($('fee').value);$('due').textContent=usd(g.total+num($('adjustment').value)+num($('fee').value))}\nfunction showTab(name){for(const n of ['Items','Source','Review']){$('tab'+n).classList.toggle('active',name===n);$(n.toLowerCase()+'View').classList.toggle('hidden',name!==n)}}\nfunction importRows(rows){orders=rows.map((r,i)=>rowMap(r,i)).filter(r=>r.name);customers=buildGroups(orders);selected='';states=new Map();logs=[];$('detail').classList.add('hidden');$('empty').classList.remove('hidden');$('search').value='';$('filter').value='all';updateList();toast('Imported '+orders.length+' 邮寄 rows for '+customers.length+' customer groups')}\n$('file').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{let data;if(/\\.csv$/i.test(f.name)){data=csv(await f.text()).slice(1)}else{data=(await readShippingXlsx(await f.arrayBuffer())).slice(1)}importRows(data);$('filename').textContent=f.name+' · 邮寄 only'}catch(err){toast('Import failed: '+err.message)}};\n$('demo').onclick=()=>{importRows([['到齐','已付','','Alisha','日本制雨靴鞋垫(蓝色,15)*1\\n日本制经典雨靴(粉色,15)*2',64,'','','',''],['差1个','已付 退20','','Alisha','护肤品x1到货\\n帽子x1缺货',39,'','','',''],['到齐','','','Aliya','儿童外套x1',38,'','','','']]);choose(customers[0].key);$('filename').textContent='Demonstration only'};\n$('clear').onclick=()=>{orders=[];customers=[];selected='';states=new Map();logs=[];$('detail').classList.add('hidden');$('empty').classList.remove('hidden');$('filename').textContent='Only the 邮寄 sheet will be imported';updateList();toast('Session cleared')};\n$('search').oninput=updateList;$('filter').onchange=updateList;for(const n of ['Items','Source','Review'])$('tab'+n).onclick=()=>showTab(n);\n$('checkAll').onclick=()=>{const g=current();if(!g)return;const s=state(g);g.items.forEach((_,i)=>s.checks[i]=true);s.verified=false;draw()};\n$('reviewDone').onclick=()=>{const g=current();if(!g)return;save();const s=state(g);if(g.issues.some((_,i)=>!s.resolved[i]))return toast('Acknowledge every review flag first');s.reviewed=true;s.verified=false;draw();toast('Review confirmed. Now verify physical items.')};\n$('confirmPacking').onclick=()=>{const g=current();if(!g)return;save();const s=state(g);if(!s.reviewed)return toast('Open Exceptions & payment and confirm review first');if(!g.items.length||g.items.some((_,i)=>!s.checks[i]))return toast('Check each item before confirming');if(g.items.some((item,i)=>!Number.isInteger(Number(s.qtyOverride[i]??item.qty))||Number(s.qtyOverride[i]??item.qty)<1))return toast('Enter verified quantities for every product line');if(g.items.some(i=>i.missing)&&!s.notes.trim())return toast('Document how missing-stock items were resolved in reviewer notes');s.verified=true;draw();toast('Bag verification recorded in this session')};\n$('adjustment').oninput=()=>{totals();save()};$('fee').oninput=()=>{totals();save()};\n$('prepare').onclick=()=>{const g=current();if(!g)return;save();const s=state(g);if(!s.verified)return toast('Verify review and bag contents first');if(!num(s.weight)||!num(s.length)||!num(s.width)||!num(s.height))return toast('Enter positive package measurements');if(g.rows.some(r=>!r.amountValid))return toast('Source amount needs correction before preparing');const lines=g.items.map((i,n)=>'• '+i.text+' — 已核对 '+(s.qtyOverride[n]??i.qty)+' 件').join('\\n');s.draft=g.name+' 您好！\\n\\n您的商品已整理，请核对：\\n'+lines+'\\n\\n商品合计：'+usd(g.total)+'\\n调整/抵扣：'+usd(s.adjustment)+'\\n运费：'+usd(s.fee)+'\\n暂计应付：'+usd(g.total+s.adjustment+s.fee)+'\\n\\n请核对商品信息，谢谢！';$('draft').value=s.draft;$('draftBox').classList.remove('hidden');logs.push({timestamp:new Date().toISOString(),customer:g.name,source_rows:g.rows.map(r=>r.row).join('|'),merchandise:g.total,adjustment:s.adjustment,shipping_fee:s.fee,provisional_due:g.total+s.adjustment+s.fee,payment:s.payment,weight_kg:s.weight,length_in:s.length,width_in:s.width,height_in:s.height,status:'Draft prepared — not shipped',notes:s.notes});toast('Draft prepared, no postage or messages sent')};\n$('copy').onclick=async()=>{if($('draftBox').classList.contains('hidden'))return toast('Prepare a draft first');try{await navigator.clipboard.writeText($('draft').value);toast('Copied for manual WeChat sending')}catch{toast('Please select and copy message manually')}};\n$('export').onclick=()=>{if(!logs.length)return toast('No drafts to export yet');const keys=Object.keys(logs[0]),rows=[keys,...logs.map(o=>keys.map(k=>o[k]))],file='\\ufeff'+rows.map(r=>r.map(v=>'\"'+String(v??'').replace(/\"/g,'\"\"')+'\"').join(',')).join('\\r\\n'),blob=new Blob([file],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='yiyi-shipping-draft-log.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};\nupdateList();\n","type":"application/javascript;charset=utf-8"},"/xlsx-reader.js":{"text":"// Compact, dependency-free XLSX reader for standard worksheet data.\n// Reads cached formula values and shared/inline strings; never evaluates formulas.\nasync function readShippingXlsx(buffer){\n const data=new Uint8Array(buffer),view=new DataView(buffer),u16=p=>view.getUint16(p,true),u32=p=>view.getUint32(p,true);\n let end=-1;for(let p=data.length-22;p>=Math.max(0,data.length-65558);p--){if(u32(p)===0x06054b50){end=p;break}}\n if(end<0)throw Error('This is not a valid .xlsx ZIP file');\n const files=new Map();let pos=u32(end+16),total=u16(end+10);\n for(let i=0;i<total;i++){if(u32(pos)!==0x02014b50)throw Error('Invalid Excel ZIP directory');const method=u16(pos+10),compressed=u32(pos+20),nameLen=u16(pos+28),extra=u16(pos+30),comment=u16(pos+32),local=u32(pos+42),name=new TextDecoder().decode(data.slice(pos+46,pos+46+nameLen));files.set(name,{method,compressed,local});pos+=46+nameLen+extra+comment}\n async function content(path){const f=files.get(path);if(!f)throw Error('Missing workbook component: '+path);const start=f.local+30+u16(f.local+26)+u16(f.local+28),bytes=data.slice(start,start+f.compressed);if(f.method===0)return new TextDecoder().decode(bytes);if(f.method!==8)throw Error('Unsupported Excel compression method');const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate-raw'));return new TextDecoder().decode(await new Response(stream).arrayBuffer())}\n const xml=s=>{const d=new DOMParser().parseFromString(s,'application/xml');if(d.querySelector('parsererror'))throw Error('Could not parse an Excel XML component');return d};\n const children=(node,name)=>Array.from(node?.children||[]).filter(e=>e.localName===name);\n const first=(node,name)=>children(node,name)[0];\n const w=xml(await content('xl/workbook.xml')),sheet=Array.from(w.getElementsByTagName('*')).find(e=>e.localName==='sheet'&&e.getAttribute('name')==='邮寄');\n if(!sheet)throw Error('Worksheet 邮寄 was not found');\n const rid=sheet.getAttribute('r:id')||sheet.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id');\n const rel=xml(await content('xl/_rels/workbook.xml.rels')),relNode=Array.from(rel.getElementsByTagName('*')).find(e=>e.localName==='Relationship'&&e.getAttribute('Id')===rid);\n if(!relNode)throw Error('Cannot locate the 邮寄 worksheet XML');\n const target=relNode.getAttribute('Target').replace(/^\\/+/,'');\n const sheetPath=target.startsWith('xl/')?target:'xl/'+target.replace(/^\\.\\//,'');\n let strings=[];if(files.has('xl/sharedStrings.xml')){const s=xml(await content('xl/sharedStrings.xml'));strings=Array.from(s.getElementsByTagName('*')).filter(e=>e.localName==='si').map(si=>Array.from(si.getElementsByTagName('*')).filter(e=>e.localName==='t').map(t=>t.textContent).join(''))}\n const doc=xml(await content(sheetPath)),rows=[];\n for(const r of Array.from(doc.getElementsByTagName('*')).filter(e=>e.localName==='row')){const rowNum=Number(r.getAttribute('r'));if(!rowNum||rowNum>100000)continue;const cells=[];for(const c of children(r,'c')){const ref=c.getAttribute('r')||'',letters=(ref.match(/^[A-Z]+/)||[])[0];if(!letters)continue;let col=0;for(const letter of letters)col=col*26+letter.charCodeAt(0)-64;col--;if(col>40)continue;const type=c.getAttribute('t'),v=first(c,'v'),inline=first(c,'is');let value=v?.textContent??'';if(type==='s')value=strings[Number(value)]??'';else if(type==='inlineStr')value=Array.from(inline?.getElementsByTagName('*')||[]).filter(e=>e.localName==='t').map(e=>e.textContent).join('');else if(type==='b')value=value==='1';else if(type!=='str'&&type!=='e'&&value!==''&&!Number.isNaN(Number(value)))value=Number(value);cells[col]=value}rows[rowNum-1]=cells}\n return rows;\n}\n","type":"application/javascript;charset=utf-8"},"/shippo-client.js":{"text":"// Shippo requests always go through the private Site's test-token-only backend.\nlet quote=null,rateId=null;\nfunction errorRate(message){$('rateError').textContent=message;$('rateError').classList.remove('hidden')}\nfunction clearRates(){quote=null;rateId=null;$('rates').classList.add('hidden');$('testLabel').classList.add('hidden');$('rateError').classList.add('hidden');$('rateChoices').replaceChildren()}\nfunction addr(prefix){const v=x=>$(prefix+x).value.trim();return {name:v('Name'),street1:v('Street'),city:v('City'),state:v('State').toUpperCase(),zip:v('Zip'),country:'US',...(v('Phone')?{phone:v('Phone')}:{})}}\nfunction completeAddress(a){return a.name&&a.street1&&a.city&&a.state&&a.zip}\nasync function shippoRequest(path,body){const r=await fetch(path,{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify(body)}),d=await r.json().catch(()=>({error:'Unreadable response'}));if(!r.ok)throw Error(d.error||'Shippo test request failed');return d}\nasync function shippoStatus(){try{const r=await fetch('/api/shippo/status',{credentials:'same-origin'}),d=await r.json();$('shippoStatus').textContent=d.configured?'TEST token connected':'Test token needed';$('shippoStatus').className='pill '+(d.configured?'':'warn');$('getRates').disabled=!d.configured}catch{$('shippoStatus').textContent='Integration unavailable';$('getRates').disabled=true}}\nfunction syncRecipient(){if(!current())return;$('toName').value=$('recipient').value;$('toPhone').value=$('phone').value;clearRates()}\nnew MutationObserver(syncRecipient).observe($('title'),{childList:true,subtree:true,characterData:true});\n$('resetRates').onclick=clearRates;\n$('getRates').onclick=async()=>{clearRates();save();const g=current();if(!g)return errorRate('Select a customer first');const s=state(g);if(!s.verified)return errorRate('Verify review and physical packing before quoting');const from=addr('from'),to=addr('to');if(!completeAddress(from)||!completeAddress(to))return errorRate('Complete sender and recipient address fields');const parcel={length:Number(s.length),width:Number(s.width),height:Number(s.height),weight:Number(s.weight),distance_unit:'in',mass_unit:'kg'};if([parcel.length,parcel.width,parcel.height,parcel.weight].some(x=>!Number.isFinite(x)||x<=0))return errorRate('Enter positive weight and dimensions');$('getRates').disabled=true;$('getRates').textContent='Quoting…';try{const d=await shippoRequest('/api/shippo/rates',{from,to,parcel});quote={customer:g.key,shipment:d.shipment_id};const rates=(d.rates||[]).filter(x=>['USPS','UPS'].includes(x.provider)).sort((a,b)=>Number(a.amount)-Number(b.amount));$('rates').classList.remove('hidden');$('rateChoices').innerHTML=rates.length?rates.map((x,i)=>'<div class=\"flag\"><label><input type=\"radio\" name=\"testRate\" value=\"'+esc(x.id)+'\" '+(i===0?'checked':'')+'>'+esc(x.provider)+' · '+esc(x.service)+' · '+esc(x.amount)+' '+esc(x.currency)+'</label></div>').join(''):'<div class=\"note\">No USPS/UPS test rates returned. Review carrier configuration and addresses.</div>';rateId=rates[0]?.id||null;$('rateChoices').querySelectorAll('[name=\"testRate\"]').forEach(el=>el.onchange=()=>rateId=el.value)}catch(e){errorRate(e.message)}finally{$('getRates').textContent='Get test rates';$('getRates').disabled=false}};\n$('createTestLabel').onclick=async()=>{const g=current();if(!g||!quote||quote.customer!==g.key)return errorRate('Request rates for the current customer');if(!rateId)return errorRate('Choose a test rate');$('createTestLabel').disabled=true;try{const d=await shippoRequest('/api/shippo/test-label',{rate_id:rateId});if(!d.was_test)throw Error('No test confirmation received');$('testLabel').replaceChildren();const head=document.createElement('b');head.textContent='TEST LABEL · '+d.status;$('testLabel').append(head);const p=document.createElement('p');p.textContent='Test tracking: '+(d.tracking_number||'Unavailable');$('testLabel').append(p);if(d.label_url){const link=document.createElement('a');link.href=d.label_url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Open TEST label PDF';$('testLabel').append(link)}$('testLabel').classList.remove('hidden')}catch(e){errorRate(e.message)}finally{$('createTestLabel').disabled=false}};\nshippoStatus();\n","type":"application/javascript;charset=utf-8"}});
